// ═══ DOUBLE-CHECKED LOCKING (old — error-prone) ═══
class OldService {
    private volatile ExpensiveResource resource;  // volatile required!

    ExpensiveResource getResource() {
        if (resource == null) {                    // first check (no lock)
            synchronized (this) {                  // lock
                if (resource == null) {             // second check (inside lock)
                    resource = new ExpensiveResource();  // create once
                }
            }
        }
        return resource;
    }
    // Problems: verbose, easy to get wrong (forget volatile = broken!),
    // JVM can't optimize as constant
}

// ═══ STABLE VALUE (JEP 502 — preview) ═══
class NewService {
    private final StableValue<ExpensiveResource> resource = StableValue.of();

    ExpensiveResource getResource() {
        return resource.orElseSet(ExpensiveResource::new);
        // First call: creates ExpensiveResource, stores it
        // All subsequent calls: returns cached value
        // Thread-safe without volatile/synchronized!
        // JVM can optimize like a final field (constant folding)
    }
}

// ═══ STABLE VALUE for lazy list/map ═══
class TradeService {
    private final StableValue<List<Trade>> cachedTrades = StableValue.of();

    List<Trade> getAllTrades() {
        return cachedTrades.orElseSet(() -> {
            log.info("Loading trades from DB — happens ONCE!");
            return tradeRepo.findAll();
        });
    }
}
