// File: src/test/java/com/bank/java8/StableValueTest.java
package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;
import static org.assertj.core.api.Assertions.assertThat;

class StableValueTest {

    // Illustrative lazy-at-most-once holder (stable-value semantics).
    static final class Lazy<T> {
        private volatile T value;
        private final Supplier<T> init;
        Lazy(Supplier<T> init) { this.init = init; }
        T get() {
            T v = value;
            if (v == null) synchronized (this) {
                if (value == null) value = init.get();
                v = value;
            }
            return v;
        }
    }

    @Test
    void initialisesAtMostOnce() {
        AtomicInteger loads = new AtomicInteger();
            Lazy<String> rates = new Lazy<>(() -> { loads.incrementAndGet();
            return "USD=83.1"; });

        assertThat(rates.get()).isEqualTo("USD=83.1");
        assertThat(rates.get()).isEqualTo("USD=83.1");   // second read, no reload
        assertThat(loads.get()).isEqualTo(1);            // loaded exactly once
    }
}
